const listClearDevComplexExecutionAgentSteps = `-- name: ListClearDevComplexExecutionAgentSteps :many
SELECT step.id, step.role_binding_id, step.step_kind, step.request_id, step.client_message_id, step.prompt_sha256, step.send_status, step.turn_id, step.final_message_id, step.final_message_text, step.message_sha256, step.requested_at, step.sent_at, step.completed_at, step.failed_at, step.reason_code FROM cleardev_complex_execution_agent_steps AS step
JOIN cleardev_complex_execution_role_bindings AS binding ON binding.id = step.role_binding_id
WHERE binding.execution_run_id = ? ORDER BY step.requested_at, step.id
`

func (q *Queries) ListClearDevComplexExecutionAgentSteps(ctx context.Context, executionRunID string) ([]CleardevComplexExecutionAgentStep, error) {
	rows, err := q.db.QueryContext(ctx, listClearDevComplexExecutionAgentSteps, executionRunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CleardevComplexExecutionAgentStep{}
	for rows.Next() {
		var i CleardevComplexExecutionAgentStep
		if err := rows.Scan(
			&i.ID,
			&i.RoleBindingID,
			&i.StepKind,
			&i.RequestID,
			&i.ClientMessageID,
			&i.PromptSha256,
			&i.SendStatus,
			&i.TurnID,
			&i.FinalMessageID,
			&i.FinalMessageText,
			&i.MessageSha256,
			&i.RequestedAt,
			&i.SentAt,
			&i.CompletedAt,
			&i.FailedAt,
			&i.ReasonCode,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

